import React, { useState } from "react";
import { useParams } from "react-router-dom";

const states = ["Andhra Pradesh","Karnataka","Tamil Nadu","Maharashtra","Delhi","Other"];

const jobSkills = {
  1: ["React", "JavaScript", "HTML", "CSS"],
  2: ["Node.js", "Express", "MongoDB"],
  3: ["Figma", "Adobe XD"],
  4: ["MongoDB","Express","React","Node"],
  5: ["Excel","SQL","Tableau"],
  6: ["AWS","Docker","Jenkins"],
  7: ["Flutter","Dart"],
  8: ["Selenium","Java"],
  9: ["SEO","Social Media","Ads"],
  10:["Recruitment","Payroll","HRMS"]
};

export default function ApplyForm() {
  const { id } = useParams();
  const [formData, setFormData] = useState({
    name: "", email: "", phone: "", state: "", city: "", pincode: "", address: "", project: "", skills: "", resume: null,
    academic: {
      tenth: { score:"", school:"" },
      diploma: { score:"", college:"", stream:"" },
      graduation: { score:"", college:"", stream:"" },
      postGraduation: { score:"", college:"", stream:"" }
    }
  });

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if(name === "resume") {
      setFormData({...formData, resume: files[0]});
    } else {
      setFormData({...formData, [name]: value});
    }
  };

  const handleAcademicChange = (level, field, value) => {
    setFormData({
      ...formData,
      academic: { ...formData.academic, [level]: {...formData.academic[level], [field]: value } }
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    alert("Application submitted!");
    console.log(formData);
  };

  return (
    <div style={{position:"relative"}}>
      {/* Company Logo */}
      <img src="/logo.png" alt="Company Logo" className="company-logo" />

      <div className="apply-form-wrapper">
        {/* Left: Primary Skills */}
        <div className="skills-box">
          <h3>Primary Skills Required</h3>
          <ul>
            {jobSkills[id]?.map((skill,i)=><li key={i}>{skill}</li>)}
          </ul>
        </div>

        {/* Middle: Application Form */}
        <div className="apply-form-box">
          <h2>Apply for this Position</h2>
          <form onSubmit={handleSubmit}>
            <label>Name:</label>
            <input type="text" name="name" onChange={handleChange} required />

            <label>Email:</label>
            <input type="email" name="email" onChange={handleChange} required />

            <label>Phone:</label>
            <input type="text" name="phone" onChange={handleChange} required />

            <label>State:</label>
            <select name="state" onChange={handleChange}>
              <option value="">Select State</option>
              {states.map((st)=><option key={st} value={st}>{st}</option>)}
            </select>

            <label>Village/City:</label>
            <input type="text" name="city" onChange={handleChange} />

            <label>Pincode:</label>
            <input type="text" name="pincode" onChange={handleChange} />

            <label>Permanent Address:</label>
            <input type="text" name="address" onChange={handleChange} />

            <label>Project Details:</label>
            <input type="text" name="project" onChange={handleChange} />

            <h4>Academic Details</h4>

            <label>10th CGPA/Percentage:</label>
            <input type="text" onChange={(e)=>handleAcademicChange("tenth","score",e.target.value)} />
            <label>School Name:</label>
            <input type="text" onChange={(e)=>handleAcademicChange("tenth","school",e.target.value)} />

            <label>Diploma CGPA/Percentage:</label>
            <input type="text" onChange={(e)=>handleAcademicChange("diploma","score",e.target.value)} />
            <label>College Name:</label>
            <input type="text" onChange={(e)=>handleAcademicChange("diploma","college",e.target.value)} />
            <label>Stream:</label>
            <input type="text" onChange={(e)=>handleAcademicChange("diploma","stream",e.target.value)} />

            <label>Graduation CGPA/Percentage:</label>
            <input type="text" onChange={(e)=>handleAcademicChange("graduation","score",e.target.value)} />
            <label>College Name:</label>
            <input type="text" onChange={(e)=>handleAcademicChange("graduation","college",e.target.value)} />
            <label>Stream:</label>
            <input type="text" onChange={(e)=>handleAcademicChange("graduation","stream",e.target.value)} />

            <label>Post Graduation CGPA/Percentage:</label>
            <input type="text" onChange={(e)=>handleAcademicChange("postGraduation","score",e.target.value)} />
            <label>College Name:</label>
            <input type="text" onChange={(e)=>handleAcademicChange("postGraduation","college",e.target.value)} />
            <label>Stream:</label>
            <input type="text" onChange={(e)=>handleAcademicChange("postGraduation","stream",e.target.value)} />

            <label>Upload Resume:</label>
            <input type="file" name="resume" onChange={handleChange} />

            <button type="submit">Submit</button>
          </form>
        </div>
      </div>
    </div>
  );
}
